import unittest

class Test(unittest.TestCase):
    def test_basic(self):
        r = word_frequencies('The cat sat on the mat. The cat ran.')
        self.assertEqual(r['the'], 3)
        self.assertEqual(r['cat'], 2)
        self.assertEqual(r['sat'], 1)
    def test_punctuation_stripped(self):
        r = word_frequencies('Hi! Hi? Hi.')
        self.assertEqual(r['hi'], 3)

if __name__ == '__main__':
    unittest.main()
